function activateCycloneLookup(s){state.cycloneLookupStorm=s}
function detail(s){const n=$('stormDetail');if(!s){n.classList.add('hidden');return}const image=s.image||s.graphic?`<figure class="official-track"><img src="${esc(s.image||s.graphic)}" ${s.imageFallback?`onerror="this.onerror=null;this.src='${esc(s.imageFallback)}'"`:''} alt="Official agency track graphic for ${esc(s.name)}"><figcaption>Original agency-issued track graphic · <a href="${esc(s.graphic)}" target="_blank" rel="noopener noreferrer">View on official website ↗</a></figcaption></figure>`:`<div class="graphic-unavailable"><b>Official track graphic unavailable</b><span>${s.tcfa?'JTWC has issued a formation alert, not a forecast-track graphic.':'The agency has not published a current track graphic. Use the official agency link below.'}</span></div>`;const facts=`<div class="storm-facts"><div><span>Current position</span><b>${esc(pos(s.position))}</b></div><div><span>Basin</span><b>${esc(basin(s))}</b></div><div><span>Official issue / update</span><b>${esc(utc(s.issued))}</b></div><div><span>Maximum wind</span><b>${Number.isFinite(s.intensity)?`${Math.round(s.intensity)} kt`:'Not supplied'}</b></div><div><span>Central pressure</span><b>${Number.isFinite(s.pressure)?`${Math.round(s.pressure)} hPa`:'Not supplied'}</b></div><div><span>Movement</span><b>${esc(s.movement)}</b></div></div>`;const table=s.forecast.length?`<section class="detail-block"><h3>Forecast positions & intensity</h3><table class="storm-table"><thead><tr><th>Valid time (UTC)</th><th>Position</th><th>Maximum wind</th><th>Official radii</th></tr></thead><tbody>${trackPoints(s).map(p=>`<tr><td>${esc(utc(p.time))}</td><td>${esc(pos(p))}</td><td>${Number.isFinite(p.intensity)?`${Math.round(p.intensity)} kt`:'—'}</td><td>${Object.keys(p.radii||{}).length?'34 / 50 / 64 kt quadrants':'Not supplied'}</td></tr>`).join('')}</tbody></table></section>`:'';const text=s.tcfa||s.discussion?`<section class="detail-block official-text"><h3>${s.tcfa?'Official JTWC formation alert':s.textTitle||'Official agency discussion'}</h3><pre>${esc(s.tcfa||s.discussion)}</pre></section>`:'';n.innerHTML=`<div class="section-heading"><div><span class="section-label">SELECTED OFFICIAL SYSTEM</span><h2>${esc(s.name)} <small>${esc(s.source)}</small></h2></div></div>${operationalMap()}${image}<div class="storm-detail-grid"><section><h3>Official system data</h3><p>${esc(s.classification)}. Values are passed through from the named agency; Weather machine does not independently forecast storm track or intensity.</p>${facts}<div class="storm-links">${s.links.map(([l,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(l)} ↗</a>`).join('')}</div></section><section class="detail-block"><h3>Airports within 300 nm</h3><p>Colours show the official 64/50/34-kt wind-radii category where supplied; otherwise they indicate geographic proximity only.</p><div id="stormAirportList"></div></section></div>${table}${cycloneLookupSection()}${text}`;n.classList.remove('hidden');state.cycloneLookup=null;activateCycloneLookup(s);buildStormMap(s)}
function destination(p,b,distance){const r=Math.PI/180,d=distance/3440,br=b*r,lat=p.lat*r,lon=p.lon*r,lat2=Math.asin(Math.sin(lat)*Math.cos(d)+Math.cos(lat)*Math.sin(d)*Math.cos(br)),lon2=lon+Math.atan2(Math.sin(br)*Math.sin(d)*Math.cos(lat),Math.cos(d)-Math.sin(lat)*Math.sin(lat2));return[lat2/r,((lon2/r+540)%360)-180]}
