function mapColour(level){return level==='extreme'?'#b5242a':level==='high'?'#e17b16':level==='moderate'?'#d4b211':'#247563'}
function drawRadii(p,selected){const colors={'34':'#e1b72e','50':'#e87d17','64':'#bc3030'},ranges={NE:[0,90],SE:[90,180],SW:[180,270],NW:[270,360]};Object.entries(p.radii||{}).forEach(([t,qs])=>Object.entries(qs||{}).forEach(([q,d])=>{if(!ranges[q]||!Number(d)||!colors[t])return;const layer=L.polygon(sector(p,...ranges[q],Number(d)),{pane:'windRadii',color:colors[t],weight:selected?2:1,opacity:selected ? .9 : .45,fillColor:colors[t],fillOpacity:selected ? .12 : .035,interactive:true}).addTo(state.layers.radii);layer.bindTooltip(`${t}-kt wind radii · ${q} quadrant · ${d} NM`,{sticky:true});layer.bindPopup(`<b>${t}-kt wind radii</b><br>${q} quadrant · ${d} NM<br>Forecast point: ${esc(utc(p.time))}`)}))}
function pointLabel(p,index){return index===0?'Current':`+${p.lead_hours??'?'} hr`}
function intensityColour(wind){return wind>=96?'#722f91':wind>=64?'#bc3030':wind>=50?'#e87d17':wind>=34?'#e1b72e':'#247563'}
const WEATHER_RISK=[
  {id:1,label:'Cat-I',roman:'I',color:'#45C4B0'},
  {id:2,label:'Cat-II',roman:'II',color:'#A8CC4A'},
  {id:3,label:'Cat-III',roman:'III',color:'#E6C84F'},
  {id:4,label:'Cat-IV',roman:'IV',color:'#F2933D'},
  {id:5,label:'Cat-V',roman:'V',color:'#E66A3C'},
  {id:6,label:'Cat-VI',roman:'VI',color:'#D94A5B'},
  {id:7,label:'Cat-VII',roman:'VII',color:'#9B59B6'},
];
function airportWeatherCategory(weather){
  const wind=weather?.wind_speed_kt,gust=weather?.wind_gust_kt,precip=weather?.precipitation_mm;
  const between=(value,low,high)=>Number.isFinite(value)&&value>=low&&value<=high;
  const pTo5=Number.isFinite(precip)&&precip>=0&&precip<=5;
  const pOver5to10=Number.isFinite(precip)&&precip>5&&precip<=10;
  const baseWind=(between(wind,15,20)||between(gust,20,25));
  // Check from highest to lowest so any overlap resolves to the highest category.
  if((Number.isFinite(wind)&&wind>25)||(Number.isFinite(gust)&&gust>35)||(Number.isFinite(precip)&&precip>10))return WEATHER_RISK[6];
  if(pOver5to10&&((Number.isFinite(wind)&&wind>20)||(Number.isFinite(gust)&&gust>30)))return WEATHER_RISK[5];
  if(pOver5to10&&(between(wind,15,20)||(Number.isFinite(gust)&&gust>=25&&gust<=30)))return WEATHER_RISK[4];
  // Cat-IV is the higher-gust band from the revised proposal. Its repeated
  // wind >20 clause was removed because Cat-III already catches that range.
  if(pTo5&&Number.isFinite(gust)&&gust>30&&gust<=35)return WEATHER_RISK[3];
  if(pTo5&&((Number.isFinite(wind)&&wind>20)||(Number.isFinite(gust)&&gust>=25&&gust<=30)))return WEATHER_RISK[2];
  if(baseWind&&Number.isFinite(precip)&&precip>1&&precip<=2.5)return WEATHER_RISK[1];
  if(baseWind&&Number.isFinite(precip)&&precip>=0&&precip<=1)return WEATHER_RISK[0];
  return null;
}
function weatherRiskKey(){const key=$('stormWeatherKey');if(!key)return;key.hidden=!$('stormAirportRiskToggle')?.checked;key.innerHTML=`<b>Airport fill · Open-Meteo Best Match</b>${WEATHER_RISK.map(item=>`<span><i style="background:${item.color}"></i>${item.label}</span>`).join('')}<span class="weather-none"><i></i>No category / unavailable</span>`}
function normalLongitude(value){return((value+540)%360)-180}
function spatialGrid(center){const side=1000,dimension=9,cell=side/dimension,rows=[];for(let row=0;row<dimension;row++){const northNm=side/2-row*cell,southNm=northNm-cell,lat=center.lat+(northNm+southNm)/120,latSouth=center.lat+southNm/60,latNorth=center.lat+northNm/60,cos=Math.max(.12,Math.cos(lat*Math.PI/180));const cells=[];for(let col=0;col<dimension;col++){const westNm=-side/2+col*cell,eastNm=westNm+cell,mapWest=center.lon+westNm/(60*cos),mapEast=center.lon+eastNm/(60*cos);cells.push({lat,lon:normalLongitude((mapWest+mapEast)/2),south:latSouth,north:latNorth,west:mapWest,east:mapEast})}rows.push(cells)}return rows.flat()}
