function spatialWindColour(value){if(!Number.isFinite(value))return null;if(value<10)return'#B9E4DC';if(value<20)return'#65BDAE';if(value<30)return'#E6D85A';if(value<40)return'#F09A47';if(value<50)return'#D85045';return'#8B4A9E'}
