function spatialLegend(){const key=$('stormSpatialKey'),wind=$('stormWindLayerToggle')?.checked,rain=$('stormPrecipLayerToggle')?.checked,barbs=$('stormWindBarbsToggle')?.checked,gust=$('stormGustBarbsToggle')?.checked;if(!key)return;const windKey=wind?`<span><b>Wind shading (kt)</b></span>${[['0–9','#B9E4DC'],['10–19','#65BDAE'],['20–29','#E6D85A'],['30–39','#F09A47'],['40–49','#D85045'],['≥50','#8B4A9E']].map(([label,color])=>`<span><i style="background:${color}"></i>${label}</span>`).join('')}`:'',rainKey=rain?`<span><b>Precipitation (mm/h)</b></span>${[['>0–0.9','#B9E2F2'],['1–2.4','#70B9DF'],['2.5–4.9','#4F7FD1'],['5–10','#E58B4C'],['>10','#B74455']].map(([label,color])=>`<span><i style="background:${color}"></i>${label}</span>`).join('')}`:'',barbKey=barbs?'<span><i style="background:#111;border-radius:50%;width:5px;height:5px"></i>Black barbs: sustained wind direction / speed</span>':'',gustKey=gust?'<span><i style="background:#111;border-radius:50%;width:5px;height:5px"></i>Black barbs: gust speed (direction from sustained wind)</span>':'';key.innerHTML=[windKey,rainKey,barbKey,gustKey].filter(Boolean).join('')}
