function windBarbIcon(speed,direction){let remaining=Math.max(0,Math.round(speed/5)*5),y=3,marks='';while(remaining>=50){marks+=`<path d="M22 ${y} L22 ${y+6} L34 ${y} Z" fill="#111" stroke="#111" stroke-width="1"/>`;remaining-=50;y+=6}while(remaining>=10){marks+=`<path d="M22 ${y} L34 ${y+5}"/>`;remaining-=10;y+=5}if(remaining>=5)marks+=`<path d="M22 ${y} L28 ${y+3}"/>`;return L.divIcon({className:'storm-wind-barb-icon',html:`<svg viewBox="0 0 44 44" aria-hidden="true"><g transform="rotate(${Math.round(direction)} 22 22)" fill="none" stroke="#111" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="22" cy="22" r="2.4" fill="#111"/><path d="M22 22 L22 2"/>${marks}</g></svg>`,iconSize:[44,44],iconAnchor:[22,22]})}
