function drawSpatialWeather(grid,locations,p){state.layers.spatial.clearLayers();state.layers.barbs.clearLayers();const windOn=$('stormWindLayerToggle')?.checked,rainOn=$('stormPrecipLayerToggle')?.checked,barbsOn=$('stormWindBarbsToggle')?.checked,gustOn=$('stormGustBarbsToggle')?.checked,activeModel=state.spatialModel;grid.forEach((cell,index)=>{const location=locations[index],wind=spatialValue(location,p.time,'wind_speed_10m'),gust=spatialValue(location,p.time,'wind_gusts_10m'),direction=spatialValue(location,p.time,'wind_direction_10m'),rain=spatialValue(location,p.time,'precipitation'),windColor=windOn?spatialWindColour(wind):null,rainColor=rainOn?spatialRainColour(rain):null,fill=windColor||rainColor;if(fill){const combined=Boolean(windColor&&rainColor),layer=L.rectangle([[cell.south,cell.west],[cell.north,cell.east]],{pane:'spatial',color:combined?rainColor:'transparent',weight:combined?2:0,fillColor:fill,fillOpacity:combined ? .42 : .5,opacity:combined ? .88 : 0,interactive:true}).addTo(state.layers.spatial);layer.bindTooltip(`<b>${esc(utc(p.time))}</b><br>${esc(activeModel==='best_match'?'Open-Meteo Best Match':activeModel==='ecmwf_ifs'?'ECMWF IFS HRES 9 km':'NOAA GFS Global')}<br>Wind: ${wind==null?'—':`${wind.toFixed(1)} kt`}<br>Gust: ${gust==null?'—':`${gust.toFixed(1)} kt`}<br>Precipitation: ${rain==null?'—':`${rain.toFixed(1)} mm/h`}`,{sticky:true})}const barbSpeed=gustOn?gust:wind;if((barbsOn||gustOn)&&Number.isFinite(barbSpeed)&&Number.isFinite(direction)){const marker=L.marker([cell.lat,cell.lon],{pane:'windBarbs',icon:windBarbIcon(barbSpeed,direction),keyboard:false}).addTo(state.layers.barbs);marker.bindTooltip(`${gustOn?'Wind gust':'Wind'}: ${barbSpeed.toFixed(1)} kt · from ${Math.round(direction)}°${gustOn?' (direction from sustained wind)':''}`,{sticky:true})}});const nw=grid[0],se=grid.at(-1),visible=windOn||rainOn||barbsOn||gustOn;if(visible&&state.map)state.map.fitBounds([[se.south,nw.west],[nw.north,se.east]],{padding:[24,24],maxZoom:6})}
async function refreshSpatialForecast(){const windOn=$('stormWindLayerToggle')?.checked,rainOn=$('stormPrecipLayerToggle')?.checked,barbsOn=$('stormWindBarbsToggle')?.checked,gustOn=$('stormGustBarbsToggle')?.checked;spatialLegend();if(!state.layers?.spatial)return;const requestId=++state.spatialRequestId;state.layers.spatial.clearLayers();state.layers.barbs.clearLayers();if(!windOn&&!rainOn&&!barbsOn&&!gustOn){$('stormSpatialStatus').textContent='Choose wind shading, precipitation, wind barbs, or wind gust barbs to load the spatial forecast.';return}const p=trackPoints(state.activeStorm||{})[state.pointIndex];if(!p){$('stormSpatialStatus').textContent='No forecast position is selected.';return}const model=state.spatialModel,grid=spatialGrid(p),key=`${model}:${String(p.time||'').slice(0,13)}:${p.lat.toFixed(2)}:${p.lon.toFixed(2)}`;state.spatialGrid=grid;$('stormSpatialStatus').textContent=`Loading ${model==='best_match'?'Open-Meteo Best Match':model==='ecmwf_ifs'?'ECMWF IFS HRES 9 km':'NOAA GFS Global'} spatial guidance for ${utc(p.time)}…`;try{let locations=state.spatialCache.get(key);if(!locations){const url=spatialForecastUrl(grid,p,model),payload=await queuedPointWeather(url);locations=Array.isArray(payload)?payload:[payload];if(locations.length!==grid.length)throw Error(`Expected ${grid.length} grid forecasts; received ${locations.length}.`);state.spatialCache.set(key,locations)}if(requestId!==state.spatialRequestId)return;drawSpatialWeather(grid,locations,p);$('stormSpatialStatus').textContent=`${model==='best_match'?'Open-Meteo Best Match':model==='ecmwf_ifs'?'ECMWF IFS HRES 9 km':'NOAA GFS Global'} · ${utc(p.time)} · 9 × 9 grid over 1000 × 1000 NM. Wind and precipitation remain as coloured background shading; enabled wind barbs are black.`}catch(error){if(requestId!==state.spatialRequestId)return;$('stormSpatialStatus').textContent=`Spatial forecast unavailable: ${error.message}`}}
function buildStormMap(s){if(!window.L||!$('selectedStormMap'))return;state.activeStorm=s;const riskNote=$('stormAirportList')?.parentElement?.querySelector('p');if(riskNote)riskNote.textContent='Airport weather-risk markers and colour categories are optional. Official cyclone wind-radii exposure remains shown separately.';if(state.map)state.map.remove();state.map=L.map('selectedStormMap',{scrollWheelZoom:false,zoomControl:true});state.map.createPane('spatial');state.map.getPane('spatial').style.zIndex=320;state.map.createPane('windRadii');state.map.getPane('windRadii').style.zIndex=350;state.map.createPane('windBarbs');state.map.getPane('windBarbs').style.zIndex=370;L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:12,attribution:'&copy; OpenStreetMap contributors'}).addTo(state.map);state.layers={spatial:L.layerGroup().addTo(state.map),barbs:L.layerGroup().addTo(state.map),track:L.layerGroup().addTo(state.map),radii:L.layerGroup().addTo(state.map),airports:L.layerGroup().addTo(state.map)};weatherRiskKey();spatialLegend();const modelSelect=$('stormSpatialModel');if(modelSelect){modelSelect.value=state.spatialModel;modelSelect.onchange=()=>{state.spatialModel=modelSelect.value;refreshSpatialForecast()}}['stormWindLayerToggle','stormPrecipLayerToggle','stormWindBarbsToggle','stormGustBarbsToggle'].forEach(id=>{const control=$(id);if(control)control.onchange=refreshSpatialForecast});const airportToggle=$('stormAirportRiskToggle');if(airportToggle)airportToggle.onchange=refreshAirportRisk;const points=trackPoints(s);L.polyline(points.map(p=>[p.lat,p.lon]),{color:'#176a63',weight:3,dashArray:'7 6'}).addTo(state.layers.track);points.forEach((p,index)=>{const colour=intensityColour(p.intensity||0),wind=Number.isFinite(p.intensity)?`${Math.round(p.intensity)} KT${Number.isFinite(p.gust)?`, GUSTS ${Math.round(p.gust)} KT`:''}`:'wind not supplied',headline=index===0?'Current position':`Forecast of +${p.lead_hours} HRS`,valid=p.valid_time||utc(p.time),motion=index>0&&p.next_vector?`<br>Movement: ${esc(p.next_vector)}`:'';const marker=L.circleMarker([p.lat,p.lon],{radius:index===state.pointIndex?9:6,color:'#17372e',fillColor:colour,fillOpacity:1,weight:2}).addTo(state.layers.track);marker.bindTooltip(`<b>${headline} / ${valid}</b><br>${esc(pos(p))}<br><b>MAX SUSTAINED WINDS - ${wind}</b>${motion}`,{sticky:true});marker.bindPopup(`<b>${headline} / ${valid}</b><br>${esc(pos(p))}<br>MAX SUSTAINED WINDS - ${wind}${motion}`);marker.on('click',()=>selectPoint(s,index))});$('stormPointControls').innerHTML=points.map((p,index)=>`<button type="button" data-point="${index}" class="${index===state.pointIndex?'active':''}">${pointLabel(p,index)} · ${esc(utc(p.time))}</button>`).join('');document.querySelectorAll('#stormPointControls [data-point]').forEach(b=>b.onclick=()=>selectPoint(s,Number(b.dataset.point)));selectPoint(s,Math.min(state.pointIndex,points.length-1),true)}
function pointWeather(latitude,longitude,time){const key=`${Number(latitude).toFixed(3)},${Number(longitude).toFixed(3)},${String(time||'').slice(0,13)}`;if(!state.pointWeatherCache.has(key)){const url=`/api/storms/point-weather?latitude=${encodeURIComponent(latitude)}&longitude=${encodeURIComponent(longitude)}&time=${encodeURIComponent(time||'')}`;state.pointWeatherCache.set(key,queuedPointWeather(url).catch(error=>{state.pointWeatherCache.delete(key);throw error}))}return state.pointWeatherCache.get(key)}
async function loadPointWeather(p){const box=$('stormPointWeather');if(!box)return;box.textContent='Loading storm-centre point weather…';try{const d=await pointWeather(p.lat,p.lon,p.time);box.innerHTML=`<b>Storm-centre point weather · ${esc(utc(d.time))}</b><span>Wind ${d.wind_speed_kt??'—'} kt${d.wind_direction!=null?` · ${Math.round(d.wind_direction)}°`:''}</span><span>Gust ${d.wind_gust_kt??'—'} kt</span><span>Rainfall ${d.precipitation_mm??'—'} mm/h</span><small>${esc(d.source)} · model guidance, not an agency cyclone-wind forecast. Open an airport marker for its airport forecast.</small>`}catch(e){box.textContent=`Storm-centre point weather unavailable: ${e.message}`}}
function airportPopupHtml(hit,p){const code=esc(hit.a.iata||hit.a.icao||'—'),direction=`${String(hit.bearing).padStart(3,'0')}° ${hit.quadrant}`,category=hit.weather?airportWeatherCategory(hit.weather):null,weather=hit.weather?`<hr><b>Airport forecast · ${esc(utc(hit.weather.time||p.time))}</b><br>Wind: ${hit.weather.wind_speed_kt??'—'} KT · Gusts: ${hit.weather.wind_gust_kt??'—'} KT<br>Precipitation: ${hit.weather.precipitation_mm??'—'} mm/h<br>Weather risk: <b style="color:${category?.color||'#aab6bc'}">${category?.label||'No category threshold met'}</b>`:`<hr><span class="airport-weather-loading">${hit.weatherError?`Airport weather unavailable: ${esc(hit.weatherError)}`:'Loading Best Match weather for this selected storm time…'}</span>`;return`<b>${code} · ${esc(hit.a.name||'Airport')}</b><br>Distance from Eye: ${Math.round(hit.d)} NM ${direction}<br>${esc(hit.label)}${weather}`}
function renderMapAirportList(hits){const list=$('stormAirportList');if(!list)return;list.innerHTML=hits.length?`<ul class="impact-list storm-map-airports">${hits.map(hit=>{const category=hit.weather?airportWeatherCategory(hit.weather):null,label=category?.label||(hit.weather?'No category threshold met':hit.weatherError?'Weather unavailable':'Weather risk loading…');return`<li><b class="impact-airport ${hit.level}">${esc(hit.a.iata||hit.a.icao||'—')}</b><span>Distance from Eye: ${Math.round(hit.d)} NM ${String(hit.bearing).padStart(3,'0')}° ${hit.quadrant} · ${esc(hit.label)}<small class="weather-risk-label" style="color:${category?.color||'#aab6bc'}">${label}</small></span></li>`}).join('')}</ul>`:'<p class="impact-note">No inventory airport is within 300 nm of this point.</p>'}
function weatherAtTime(location,targetTime){const h=location?.hourly||{},times=h.time||[],target=Date.parse(targetTime);if(!times.length||!Number.isFinite(target))return null;let index=0;for(let i=1;i<times.length;i++)if(Math.abs(Date.parse(`${times[i]}Z`)-target)<Math.abs(Date.parse(`${times[index]}Z`)-target))index=i;const wind=h.wind_speed_10m?.[index],gust=h.wind_gusts_10m?.[index],precip=h.precipitation?.[index];if(wind==null&&gust==null&&precip==null)return null;return{time:`${times[index]}Z`,wind_speed_kt:wind==null?null:Math.round(wind*.539957*10)/10,wind_gust_kt:gust==null?null:Math.round(gust*.539957*10)/10,precipitation_mm:precip==null?null:Number(precip)}}
function airportWeatherBatchUrl(hits,date){const ordered=[...hits].sort((a,b)=>String(a.a.icao||a.a.iata||'').localeCompare(String(b.a.icao||b.a.iata||''))||Number(a.a.lat)-Number(b.a.lat)||Number(a.a.lon)-Number(b.a.lon)),params=new URLSearchParams({latitude:ordered.map(x=>Number(x.a.lat).toFixed(3)).join(','),longitude:ordered.map(x=>Number(x.a.lon).toFixed(3)).join(','),date});return{url:`/api/storms/airport-weather?${params}`,ordered}}
function scheduleAirportWeatherBatch(hits,p){const requestId=++state.airportWeatherRequestId;if(airportWeatherTimer)clearTimeout(airportWeatherTimer);if(!hits.length)return;const date=String(p.time||new Date().toISOString()).slice(0,10),ordered=[...hits].sort((a,b)=>String(a.a.icao||a.a.iata||'').localeCompare(String(b.a.icao||b.a.iata||''))||Number(a.a.lat)-Number(b.a.lat)||Number(a.a.lon)-Number(b.a.lon)),batches=[];for(let i=0;i<ordered.length;i+=25)batches.push(ordered.slice(i,i+25));hits.forEach(hit=>{hit.weather=null;hit.weatherError='';hit.marker?.setStyle({fillColor:'#75858b',fillOpacity:.9})});renderMapAirportList(hits);$('stormMapNote').textContent=`${pointLabel(p,state.pointIndex)} selected · ${utc(p.time)}. Preparing Best Match weather for ${hits.length} airports…`;airportWeatherTimer=setTimeout(()=>{airportWeatherTimer=null;loadAirportWeatherBatch(hits,p,requestId,date,batches)},450)}
async function loadAirportWeatherBatch(hits,p,requestId,date,batches){
  for(let batchIndex=0;batchIndex<batches.length;batchIndex++){const batch=batches[batchIndex];if(requestId!==state.airportWeatherRequestId)return;const{url,ordered:batchOrdered}=airportWeatherBatchUrl(batch,date);try{const payload=await queuedPointWeather(url),locations=Array.isArray(payload)?payload:[payload];batchOrdered.forEach((hit,index)=>{hit.weather=weatherAtTime(locations[index],p.time);if(!hit.weather)hit.weatherError='No hourly guidance returned';hit.marker?.setStyle({fillColor:airportWeatherCategory(hit.weather)?.color||'#75858b',fillOpacity:.94});if(hit.marker)hit.marker.setPopupContent(airportPopupHtml(hit,p))})}catch(error){const remaining=batches.slice(batchIndex).flat();remaining.forEach(hit=>{hit.weatherError=error.message;hit.marker?.setStyle({fillColor:'#75858b',fillOpacity:.9});hit.marker?.setPopupContent(airportPopupHtml(hit,p))});if(requestId!==state.airportWeatherRequestId)return;renderMapAirportList(hits);break}if(requestId!==state.airportWeatherRequestId)return;renderMapAirportList(hits)}
  if(requestId===state.airportWeatherRequestId){const available=hits.filter(hit=>hit.weather).length;$('stormMapNote').textContent=`${pointLabel(p,state.pointIndex)} selected · ${utc(p.time)}. ${hits.length} airports within 300 nm; weather risk colours loaded for ${available}/${hits.length} using Open-Meteo Best Match.`}}
function refreshAirportRisk(){if(!state.map||!state.layers?.airports)return;const toggle=$('stormAirportRiskToggle'),enabled=Boolean(toggle?.checked),p=trackPoints(state.activeStorm||{})[state.pointIndex];weatherRiskKey();state.layers.airports.clearLayers();if(airportWeatherTimer)clearTimeout(airportWeatherTimer);state.airportWeatherRequestId++;const list=$('stormAirportList');if(!enabled){if(list)list.innerHTML='<p class="impact-note">Airport weather risk is off. Turn on “Airport weather risk” above to load and display airport categories.</p>';if(p)$('stormMapNote').textContent=`${pointLabel(p,state.pointIndex)} selected · ${utc(p.time)}. Airport weather-risk display is off.`;return}if(!p)return;const hits=pointImpacts(p);hits.forEach(hit=>{const marker=L.circleMarker([hit.a.lat,hit.a.lon],{radius:7,color:'#172329',fillColor:'#75858b',fillOpacity:.9,weight:2}).addTo(state.layers.airports);hit.marker=marker;const code=esc(hit.a.iata||hit.a.icao||'—');marker.bindTooltip(code,{permanent:true,direction:'right',className:'storm-airport-label'});marker.bindPopup(airportPopupHtml(hit,p))});if(!hits.length){renderMapAirportList(hits);$('stormMapNote').textContent=`${pointLabel(p,state.pointIndex)} selected · no inventory airports within 300 nm.`;return}renderMapAirportList(hits);scheduleAirportWeatherBatch(hits,p)}
function selectPoint(s,index,initial=false){const points=trackPoints(s),p=points[index];if(!p||!state.map)return;state.pointIndex=index;state.layers.radii.clearLayers();points.forEach((point,i)=>drawRadii(point,i===index));document.querySelectorAll('#stormPointControls [data-point]').forEach(b=>b.classList.toggle('active',Number(b.dataset.point)===index));const currentZoom=state.map.getZoom(),minimumZoom=initial?4:5,zoom=Number.isFinite(currentZoom)?Math.max(currentZoom,minimumZoom):minimumZoom;state.map.setView([p.lat,p.lon],zoom);loadPointWeather(p);refreshAirportRisk();refreshSpatialForecast()}
function select(id){const s=state.systems.find(x=>x.id===id);if(!s)return;state.selectedId=id;state.pointIndex=0;cards();detail(s);$('stormDetail').scrollIntoView({behavior:'smooth',block:'start'})}
async function load(){const refresh=$('refreshStorms');refresh.disabled=true;$('stormNotice').classList.remove('error');$('stormNotice').textContent='Retrieving official NHC / CPHC and JTWC advisory feeds…';try{const[n,j,i,a,ports,t]=await Promise.allSettled([api('/api/storms/nhc'),api('/api/storms/jtwc-warnings'),api('/api/storms/imd'),api('/api/storms/nrl'),api('/api/storms/airports'),api('/api/storms/jtwc-tcfas')]),alerts=t.status==='fulfilled'?(t.value.alerts||[]):[],codes=new Set(alerts.map(x=>String(x.invest||'').toUpperCase())),systems=[];if(n.status==='fulfilled')systems.push(...nhc(n.value));if(j.status==='fulfilled')systems.push(...jtwc(j.value));if(i.status==='fulfilled')systems.push(...imdSystems(i.value));if(a.status==='fulfilled')systems.push(...nrl(a.value,codes));state.airports=ports.status==='fulfilled'?ports.value:[];systems.forEach(s=>{const alert=alerts.find(x=>String(x.invest||'').toUpperCase()===s.code);if(alert?.text){s.tcfa=alert.text;s.links.splice(1,0,['JTWC TCFA text',alert.url])}});await Promise.allSettled(systems.filter(s=>s.source==='NHC / CPHC').map(enrich));state.systems=systems;state.selectedId=systems[0]?.id||null;$('stormCount').textContent=systems.length?`${systems.length} active system${systems.length===1?'':'s'}`:'No active systems returned';$('stormPositions').textContent=`${systems.reduce((n,s)=>n+s.forecast.length,0)} agency forecast points`;$('stormImpact').textContent=state.airports.length?'Local airport inventory ready':'Airport screening unavailable';cards();detail(systems[0]);$('stormNotice').textContent='Official feeds loaded. Select one system to load its operational map; map tiles and point weather are requested only then.'}catch(e){state.systems=[];cards();detail(null);$('stormNotice').classList.add('error');$('stormNotice').textContent=`Unable to load official storm feeds: ${e.message||'unknown error'}`}finally{refresh.disabled=false}}
function imdSystems(){return[]}
// The lookup section is recreated every time the selected storm changes.
// Delegated events keep its buttons and selector connected after every redraw,
// rather than retaining a handler on a stale <select> element.
document.addEventListener('click',event=>{if(event.target.closest('#cycloneLookupRun')&&state.cycloneLookupStorm)buildCycloneLookup(state.cycloneLookupStorm);if(event.target.closest('#cycloneLookupCsv')&&state.cycloneLookup)downloadCycloneCsv(selectedCycloneRows())});
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target?.id==='cycloneAirportCode'&&state.cycloneLookupStorm){event.preventDefault();buildCycloneLookup(state.cycloneLookupStorm)}});
document.addEventListener('change',event=>{if(event.target?.id==='cycloneModel')selectCycloneModel(event.target)});
$('refreshStorms').onclick=load;load();
